import React from 'react';
import { useState } from 'react';
import logo from '../../../assets/logo.png';

function Navbar(){
    const [isOpen, setIsOpen] = useState(false);
    return(
    <header className="bg-[#FDF8F3] border-b border-[#E1D5C9] px-4 py-3 md:px-8 md:py-4">
      <div className="flex items-center justify-between">
        <img src="/logo.png" alt="Logo" className="h-10 md:h-12" />

        {/* Hamburger Button */}
        <button
          className="md:hidden text-2xl text-[#292929] focus:outline-none"
          onClick={() => setIsOpen(!isOpen)}
          aria-label="Toggle Navigation"
        >
          ☰
        </button>
      </div>

      {/* Navigation Menu */}
      <nav
        className={`${
          isOpen ? "flex" : "hidden"
        } flex-col md:flex md:flex-row md:items-center md:justify-between mt-3 md:mt-0`}
      >
        <div className="flex flex-col md:flex-row gap-2 md:gap-6 text-[#292929] font-semibold text-base sm:text-lg">
          <a href="#" className="text-[#f48f0f]">Home</a>
          <a href="#">About</a>
          <a href="#">Gallery</a>
          <a href="#">Education</a>
        </div>

        <div className="mt-3 md:mt-0">
          <button className="bg-[#F48F0F] text-[#292929] py-2 px-5 rounded-full font-semibold text-sm sm:text-base">
            Become a member
          </button>
        </div>
      </nav>
    </header>
    );
}

export default Navbar;
